'use strict';

var resolve = require( './../lib' );

var doc = {
	'foo': [ 'bar', 'baz' ],
	'': 0,
	'a/b': 1,
	'm~n': 8
};

var out = resolve( doc, '/foo' );
console.log( out );
// => { 'target': { 'foo': [...], ... }, 'key': 'foo', 'value': [ 'bar', 'baz' ] }

out = resolve( doc, '/foo/0' );
console.log( out );
// => { 'target': [ 'bar', 'baz' ], 'key': 0, 'value': 'bar' }

out = resolve( doc, '/' );
console.log( out );
// => { 'target': { ... }, 'key': '', 'value': 0 }

out = resolve( doc, '/a~1b' );
console.log( out );
// => { 'target': { ... }, 'key': 'a/b', 'value': 1 }

out = resolve( doc, '/m~0n' );
console.log( out );
// => { 'target': { ... }, 'key': 'm~n', 'value': 8 }

out = resolve( doc, '' );
console.log( out );
// => { 'target': null, 'key': null, 'value': { ... } }

out = resolve( doc, '/foo/-' );
console.log( out );
// => { 'target': [ 'bar', 'baz' ], 'key': 2, 'value': undefined }
